    coordinator: new Proxy({}, { get: (_target, key) => () => { fleetCalls.push(key); return []; } }),
    coordination, sessions, identityProvider, repoIds: ['repo-a'], allowedOrigins: [ORIGIN], now: () => now,
    ...overrides,
  });
