    appendFile: (...args) => {
      appends += 1;
      if (appends === 2) throw new Error('audit disk unavailable');
      const [path, data] = args;
      appendFileSync(path, data, 'utf8');
    },
  });
  const calls = [];
  const web = new WebNorthbound({
    coordinator: { async spawn() { calls.push('spawn'); return { id: 'w-1' }; } }, coordination,
